import {readFile,writeFile,copyFile,readdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const dir='docs/presentation/20261021-handoff',external='/Users/ASUS/Desktop/nus- learning/outputs/releaseguard-handoff-20261021';
const json=async path=>JSON.parse(await readFile(path,'utf8'));
await copyFile(external+'/final/ReleaseGuard_Presentation_v4_Handoff_20261021.pptx',dir+'/ReleaseGuard_Presentation_v4_Handoff_20261021.pptx');
const notes=await json(external+'/build/speaker-notes.json');
await writeFile(dir+'/Speaker_Notes_EN_ZH.txt','ReleaseGuard 演讲稿与中文提示\n35分钟正文 + 5分钟Q&A；隐藏页仅追问时使用。\n成员职责不是独立贡献证明。历史回放，不新增模型调用。\n\n'+notes.map(row=>`Slide ${row.slide}${row.hidden?'（隐藏备份）':''}\n${row.notes}\n`).join('\n'),{flag:process.argv.includes('--refresh-handoff')?'w':'wx'});
const sources=[['wire3-protocol','wire v3 · 3条协议实验 · 19 Oct','docs/evidence/semantic-review-wire-v3-real-2026-10-19/FINAL-RESULT.json'],['wire3-development','wire v3 · 17条开发实验 · 19 Oct','docs/evidence/semantic-review-wire-v3-cross-scenario-dev-2026-10-19/FINAL-RESULT.json'],['targeted10','wire v3 · 10条定向实验 · 21 Oct','docs/evidence/hybrid-wire-v3-targeted-pairs-2026-10-21/FINAL-RESULT.json']];
const datasets=[];
for(const [id,label,path] of sources){const source=await json(path),targeted=id==='targeted10';let records;
 if(targeted){records=[];for(const row of source.rows){const record=await json('docs/evidence/hybrid-wire-v3-targeted-pairs-2026-10-21/result-'+row.sequence+'.json');records.push({id:record.anonymousId,sequence:record.sequence,question:record.question,answer:record.originalAnswer,facts:record.facts,decision:record.decision,contract:record.contract,reference:record.reference,protocol:record.protocol,semantic:record.semantic,aggregate:record.aggregate,rawReview:await readFile(record.rawReviewPath,'utf8'),rawReviewPath:record.rawReviewPath,derived:record.derived,provider:record.providerMetadata});}}
 else{records=[];for(const record of source.results){const rawPath=path.slice(0,path.lastIndexOf('/'))+'/raw-provider/'+record.rawReviewTextFile;records.push({id:record.sampleId,sequence:record.sequence??record.experimentSequence,question:record.question,answer:record.originalResponse,reference:record.reference,protocol:record.protocol,semantic:record.semantic,aggregate:record.aggregate,rawReview:await readFile(rawPath,'utf8'),rawReviewPath:rawPath,derived:record.derivedReview,provider:record.provider});}}
 datasets.push({id,label,sourcePath:path,sourceSha256:createHash('sha256').update(await readFile(path)).digest('hex'),experimentId:source.experimentId,scope:targeted?'TARGETED_VALIDATION_FAILED. Valid protocol 10/10, designated critical rule matches 4/5. All five negatives blocked.':id==='wire3-protocol'?'Historical 3-case protocol experiment only.':'Historical 17-case development set only. Separate from the 3-case run.',records});
}
const r2=await json('docs/evidence/standard-policy-review-r2-offline-2026-10-21/FINAL-OFFLINE-VERIFICATION.json');
const data={datasets,r2:{revision:r2.revision,realRequests:r2.realRequests,testExitCode:r2.testExitCode,referenceSamples:r2.referenceSamples,status:'新定义尚未经过真实模型验证。候选未启用。仅离线程序检查，不展示模拟模型成绩。',sourcePath:'docs/evidence/standard-policy-review-r2-offline-2026-10-21/FINAL-OFFLINE-VERIFICATION.json'}};
await writeFile(dir+'/Replay_Data.json',JSON.stringify(data,null,2)+'\n',{flag:process.argv.includes('--refresh-handoff')?'w':'wx'});
const encoded=JSON.stringify(data).replaceAll('<','\\u003c');
const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ReleaseGuard 历史证据回放</title><style>body{font:17px/1.6 Arial,sans-serif;color:#172842;margin:32px auto;max-width:1150px;padding:0 20px}h1{font-size:30px}h2{font-size:22px;color:#173f7e}label{display:inline-block;margin:8px 20px 8px 0}select,button{font:inherit;padding:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f5f7;padding:20px;border-left:4px solid #527aac}small{color:#555}.warning{color:#983d16;font-weight:bold}.row{display:flex;gap:24px;flex-wrap:wrap}.row section{flex:1;min-width:300px}details{margin:18px 0}a{color:#173f7e}</style><h1>ReleaseGuard：历史真实运行回放</h1><p class="warning">仅浏览保存证据。无网络、无模型调用、无审批或部署。不同版本与实验不合并。</p><label>实验 <select id="experiment"></select></label><label id="caseLabel">样本 <select id="sample"></select></label><div id="main"></div><p><small>原客户回答为虚构参考文本，真实运行的是对应评审调用。参考来源是项目AI标注，不是真人盲审。正式路径不变，shadowOnly=true，reviewer=calibration_pending。</small></p><script id="data" type="application/json">${encoded}</script><script>const data=JSON.parse(document.getElementById('data').textContent),experiment=document.getElementById('experiment'),sample=document.getElementById('sample'),main=document.getElementById('main');for(const set of data.datasets){let option=document.createElement('option');option.value=set.id;option.textContent=set.label;experiment.append(option)}let extra=document.createElement('option');extra.value='r2';extra.textContent='r2规则修订：仅离线，未真实验证';experiment.append(extra);function node(tag,text){const element=document.createElement(tag);element.textContent=typeof text==='string'?text:JSON.stringify(text,null,2);return element}function section(title,value){main.append(node('h2',title),node('pre',value))}function draw(){main.replaceChildren();if(experiment.value==='r2'){document.getElementById('caseLabel').hidden=true;section('未启用候选：不是模型通过结果',data.r2);return}document.getElementById('caseLabel').hidden=false;const set=data.datasets.find(set=>set.id===experiment.value),record=set.records[Number(sample.value)||0];main.append(node('p',set.experimentId),node('p',set.scope),node('small',set.sourcePath+'\\nSHA256: '+set.sourceSha256));section('客户问题',record.question);section('原始客户参考回答（虚构文本，非客服生成成绩）',record.answer);section('协议与语义结果（正式交付资格另列）',{protocol:record.protocol,semantic:record.semantic,delivery:record.aggregate?.candidateDeliveryStatus,qualification:record.aggregate?.reviewerValidationStatus});section('真实评审原文（未经修改）',record.rawReview);section('来源文件',record.rawReviewPath);const details=document.createElement('details');details.append(node('summary','展开事实、决策、契约、标签及逐规则记录'),node('pre',{facts:record.facts,decision:record.decision,contract:record.contract,reference:record.reference,derived:record.derived,provider:record.provider}));main.append(details);if(set.id==='targeted10'&&record.sequence===10)main.append(node('p','指定规则STANDARD_POLICY仍passed；原评审已在额外声明与矛盾项识别同一个政策冲突。本次冻结标准仍失败，不追认通过。'))}function choose(){sample.replaceChildren();const set=data.datasets.find(set=>set.id===experiment.value);if(set)for(const [i,record]of set.records.entries()){const option=document.createElement('option');option.value=String(i);option.textContent='执行'+record.sequence+' · '+record.id;sample.append(option)}draw()}experiment.addEventListener('change',choose);sample.addEventListener('change',draw);choose();</script></html>`;
await writeFile(dir+'/Historical_Review_Replay.html',html,{flag:process.argv.includes('--refresh-handoff')?'w':'wx'});
const files=[];for(const name of await readdir(dir)){if(name==='DELIVERY-MANIFEST.json')continue;const path=dir+'/'+name;files.push({path,sha256:createHash('sha256').update(await readFile(path)).digest('hex')});}
await writeFile(dir+'/DELIVERY-MANIFEST.json',JSON.stringify({at:new Date().toISOString(),files,customerModelCalls:0,reviewerModelCalls:0,historicalReplay:true,noRuntimeActivation:true},null,2)+'\n',{flag:process.argv.includes('--refresh-handoff')?'w':'wx'});
console.log(JSON.stringify({dir,slides:30,notes:notes.length,replayDatasets:datasets.map(set=>({id:set.id,records:set.records.length})),modelCalls:0}));
